const headers = $json.headers ?? {};
const query = $json.query ?? {};
const tokenHeader = String(headers['x-govhub-token'] || headers['X-GOVHUB-TOKEN'] || '').trim();
const allowed = String($env.GOVHUB_TOKENS || '').split(',').map(v => v.trim()).filter(Boolean);
if (!tokenHeader || !allowed.includes(tokenHeader)) { return [{json:{ok:false,statusCode:401,error_code:'AUTH_INVALID_TOKEN',message:'invalid token'}}]; }
let scopes = [];
try { const m = JSON.parse(String($env.GOVHUB_TOKEN_SCOPES_JSON || '{}')); if (Array.isArray(m[tokenHeader])) scopes = m[tokenHeader]; } catch {}
if (!(scopes.includes('m:p') || scopes.includes('missions:pull'))) { return [{json:{ok:false,statusCode:403,error_code:'AUTH_SCOPE_REQUIRED',message:'missing pull scope'}}]; }
const repo_key = String(query.repo_key || '').trim();
const agent_id = String(query.agent_id || '').trim();
if (!repo_key || !agent_id) { return [{json:{ok:false,statusCode:400,error_code:'MISSIONS_NEXT_INVALID',message:'repo_key and agent_id required'}}]; }
const esc=(v)=>String(v).replace(/'/g,"''");
return [{json:{ok:true, repo_key, agent_id, repo_key_sql:esc(repo_key), agent_id_sql:esc(agent_id)}}];
